use std::io::{self, Read};

fn input() -> Vec<String> {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    s.split_whitespace().map(|t| t.to_string()).collect()
}

/// The longest run of equal values, as (start index, length).
///
/// The run in progress has to be considered once the loop ends, which
/// is what the original forgot: the check only happened when the value
/// changed, and the last run never changes.
fn longest_run(xs: &[i64]) -> (usize, usize) {
    if xs.is_empty() {
        return (0, 0);
    }
    let mut best_start = 0usize;
    let mut best_len = 1usize;
    let mut start = 0usize;

    for i in 1..xs.len() {
        if xs[i] != xs[i - 1] {
            let len = i - start;
            if len > best_len {
                best_len = len;
                best_start = start;
            }
            start = i;
        }
    }

    // The run that was in progress when the data ran out.
    let len = xs.len() - start;
    if len > best_len {
        best_len = len;
        best_start = start;
    }

    (best_start, best_len)
}

fn main() {
    let t = input();
    if t.is_empty() {
        return;
    }
    let n: usize = t[0].parse().unwrap();
    let xs: Vec<i64> = t[1..1 + n].iter().map(|s| s.parse().unwrap()).collect();

    let (start, len) = longest_run(&xs);
    if xs.is_empty() {
        println!("none");
    } else {
        println!("start {}", start);
        println!("length {}", len);
        println!("value {}", xs[start]);
    }
}
